# Patrón Strategy para serialización
from abc import ABC, abstractmethod
import json

class Serializador(ABC):
    @abstractmethod
    def serializar(self, datos: dict) -> str: ...
    @abstractmethod
    def deserializar(self, texto: str) -> dict: ...

class JSONSerializador(Serializador):
    def serializar(self, datos: dict) -> str:
        return json.dumps(datos, ensure_ascii=False)
    def deserializar(self, texto: str) -> dict:
        return json.loads(texto)

s = JSONSerializador()
codificado = s.serializar({"nombre": "Ana", "edad": 30})
print(codificado)
print(s.deserializar(codificado))

# Patrón Observer
from abc import ABC, abstractmethod

class Observador(ABC):
    @abstractmethod
    def actualizar(self, evento: str, datos: dict) -> None: ...

class Sujeto:
    def __init__(self):
        self._observadores: list[Observador] = []

    def suscribir(self, obs: Observador) -> None:
        self._observadores.append(obs)

    def notificar(self, evento: str, datos: dict = {}) -> None:
        for obs in self._observadores:
            obs.actualizar(evento, datos)

class Logger(Observador):
    def actualizar(self, evento: str, datos: dict) -> None:
        print(f"[LOG] {evento}: {datos}")

bus = Sujeto()
bus.suscribir(Logger())
bus.notificar("usuario_creado", {"nombre": "Ana"})

# Observer con weakrefs (sin memory leak)
import weakref
from typing import Callable

class Señal:
    def __init__(self):
        self._slots: list = []

    def conectar(self, slot: Callable) -> None:
        self._slots.append(weakref.WeakMethod(slot) if hasattr(slot, "__self__") else weakref.ref(slot))

    def emitir(self, *args, **kwargs) -> None:
        muertos = []
        for ref in self._slots:
            slot = ref()
            if slot is None:
                muertos.append(ref)
            else:
                slot(*args, **kwargs)
        for ref in muertos:
            self._slots.remove(ref)

# Strategy con funciones (pythónico)
from typing import Callable

def validar_email(s: str) -> bool:
    return "@" in s and "." in s.split("@")[-1]

def validar_telefono(s: str) -> bool:
    return s.replace("-", "").replace("+", "").isdigit()

def validar(valor: str, estrategia: Callable[[str], bool]) -> bool:
    return estrategia(valor)

print(validar("user@mail.com", validar_email))  # True
print(validar("+54-911-1234", validar_telefono))  # True

