from abc import ABC, abstractmethod

class EstrategiaOrden(ABC):
    @abstractmethod
    def ordenar(self, datos: list) -> list: ...

class OrdenBurbujas(EstrategiaOrden):
    def ordenar(self, datos: list) -> list:
        d = datos[:]
        n = len(d)
        for i in range(n):
            for j in range(0, n-i-1):
                if d[j] > d[j+1]:
                    d[j], d[j+1] = d[j+1], d[j]
        return d

class OrdenPython(EstrategiaOrden):
    def ordenar(self, datos: list) -> list:
        return sorted(datos)

class Ordenador:
    def __init__(self, estrategia: EstrategiaOrden):
        self.estrategia = estrategia

    def ejecutar(self, datos: list) -> list:
        return self.estrategia.ordenar(datos)

ord = Ordenador(OrdenPython())
print(ord.ejecutar([3, 1, 4, 1, 5, 9]))

# Observer con events dict (pythónico)
from collections import defaultdict
from typing import Callable

class EventBus:
    def __init__(self):
        self._handlers: dict = defaultdict(list)

    def on(self, evento: str, handler: Callable) -> None:
        self._handlers[evento].append(handler)

    def emit(self, evento: str, **datos) -> None:
        for handler in self._handlers[evento]:
            handler(**datos)

bus = EventBus()

@bus.on("login")
def log_login(usuario, **_):
    print(f"Usuario {usuario} inició sesión")

bus.emit("login", usuario="ana", ip="192.168.1.1")

