using UnityEngine.Events;

namespace Fjord.XRInteraction.XRUnityEvents
{
    [System.Serializable]
    public class XRButtonLongPressUnityEvent : XRButtonDatumUnityEvent
    {
        public float longPressDuration = 1.0f; // Default long-press duration in seconds
        private bool isButtonPressed = false;
        private float pressStartTime = 0f;

        public void OnButtonPressed(XRButtonDatum button)
        {
            isButtonPressed = true;
            pressStartTime = Time.time;
            InvokeRepeating("CheckLongPress", 0f, 0.1f); // Check for long-press every 0.1 seconds
        }

