function parsePhpCodeSnippet($codeSnippet) {
    // Remove leading and trailing whitespace
    $codeSnippet = trim($codeSnippet);

    // Extract the namespace and class name using regular expression
    preg_match('/^\'\s*([a-zA-Z\\\]+)\\\([a-zA-Z]+)\'/i', $codeSnippet, $matches);

