2. A method to stop polling for messages, which should cancel any ongoing polling tasks.
3. A method to handle received messages, which should raise the NachrichtErhalten event to notify subscribers of the new message.

You should also consider handling potential concurrency issues when implementing the polling and message handling functionality.

Implement the necessary methods and handle potential concurrency issues to ensure the ChatPollingService functions correctly.

### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public delegate void NachrichtErhaltenDelegate(string message);

public interface IChatService
{
    Task<IEnumerable<string>> GetNewMessagesAsync();
}

public class Angebot { }

public class ChatPollingService
{
    private Semaphore getNachrichtenMutex;
    private IChatService _chatService;
    private Dictionary<Angebot, CancellationTokenSource> _pollingTasks;

    public event NachrichtErhaltenDelegate NachrichtErhalten;

    public ChatPollingService(IChatService chatService)
    {
        getNachrichtenMutex = new Semaphore(1, 1);
        _chatService = chatService;
        _pollingTasks = new Dictionary<Angebot, CancellationTokenSource>();
    }

    public void StartPolling()
    {
        CancellationTokenSource cancellationTokenSource = new CancellationTokenSource();
        _pollingTasks.Add(new Angebot(), cancellationTokenSource);

        Task.Run(async () =>
        {
            while (!cancellationTokenSource.Token.IsCancellationRequested)
            {
                try
                {
                    IEnumerable<string> newMessages = await _chatService.GetNewMessagesAsync();
                    foreach (string message in newMessages)
                    {
                        HandleReceivedMessage(message);
                    }
                }
                catch (OperationCanceledException)
                {
                    // Handle cancellation
                }
                catch (Exception ex)
                {
                    // Handle other exceptions
                }

                await Task.Delay(TimeSpan.FromSeconds(5), cancellationTokenSource.Token);
            }
        }, cancellationTokenSource.Token);
    }

    public void StopPolling()
    {
        foreach (var task in _pollingTasks.Values)
        {
            task.Cancel();
        }
        _pollingTasks.Clear();
    }

    private void HandleReceivedMessage(string message)
    {
        // Ensure thread safety when raising the event
        getNachrichtenMutex.WaitOne();
        NachrichtErhalten?.Invoke(message);
        getNachrichtenMutex.Release();
    }
}
```

In the solution, the StartPolling method initiates a background task to periodically check for new messages from the chat service. The StopPolling method cancels any ongoing polling tasks, and the HandleReceivedMessage method raises the NachrichtErhalten event to notify subscribers of the new message while ensuring thread safety using a semaphore.

