```typescript
// Define the ISimpleEvent interface
interface ISimpleEvent<T> {
    subscribe(handler: (data: T) => void): void;
    unsubscribe(handler: (data: T) => void): void;
    asEvent(): ISimpleEvent<T>;
}

// Define the AbstractExpLevel class
class AbstractExpLevel {
    level: number;

    constructor(level: number) {
        this.level = level;
    }
}

// Define the LevelUpEventProvider class
class LevelUpEventProvider {
    private _onLevelUp: ISimpleEvent<AbstractExpLevel>;

    constructor() {
        this._onLevelUp = {
            handlers: [],
            subscribe: function (handler) {
                this.handlers.push(handler);
            },
            unsubscribe: function (handler) {
                this.handlers = this.handlers.filter(h => h !== handler);
            },
            asEvent: function () {
                return this;
            },
            trigger: function (data) {
                this.handlers.forEach(handler => handler(data));
            }
        };
    }

    get onLevelUp(): ISimpleEvent<AbstractExpLevel> {
        return this._onLevelUp.asEvent();
    }

    levelUp(newLevel: number) {
        const expLevel = new AbstractExpLevel(newLevel);
        this._onLevelUp.trigger(expLevel);
    }
}

