import { Observable } from 'rxjs';

export function monitorAdapterState(adapterFactory: AdapterFactory): Observable<AdapterEvent> {
    const adapterFactoryEvents$ = adapterFactoryObservable(adapterFactory);

    return new Observable<AdapterEvent>(observer => {
        const subscription = adapterFactoryEvents$.subscribe(event => {
            if (event.eventType === AdapterFactoryEventType.Added) {
                const adapterEvents$ = openAdapterObservable(event.adapter);
                const adapterSubscription = adapterEvents$.subscribe(adapterEvent => {
                    observer.next(adapterEvent);
                });
            } else if (event.eventType === AdapterFactoryEventType.Removed) {
                closeAdapterObservable(event.adapter);
                // Handle removal event if needed
            }
        });

        return () => {
            subscription.unsubscribe();
        };
    });
}
