```swift
import RxSwift

extension ObservableType {
    /**
     Projects each element of an observable sequence into a new form by incorporating the element's index.

     - parameter transform: A transform function to apply to each source element and its index.
     - returns: An observable sequence whose elements are the result of invoking the transform function on each element of the source.
     */
    func mapWithIndex<R>(_ transform: @escaping (Element, Int) throws -> R) -> Observable<R> {
        return Observable.create { observer in
            var index = 0
            let disposable = self.subscribe { event in
                switch event {
                case .next(let element):
                    do {
                        let transformedElement = try transform(element, index)
                        observer.on(.next(transformedElement))
                        index += 1
                    } catch {
                        observer.on(.error(error))
                    }
                case .error(let error):
                    observer.on(.error(error))
                case .completed:
                    observer.on(.completed)
                }
            }
            return disposable
        }
    }
}
