```rust
use std::ffi::c_void;

trait FileObserver {
    fn on_rename(&self, file_path: &str);
    fn on_save(&self, file_path: &str);
    fn on_close(&self, file_path: &str);
}

struct File {
    path: String,
    observers: Vec<Box<dyn FileObserver>>,
}

impl File {
    fn new(path: String) -> Self {
        File {
            path,
            observers: Vec::new(),
        }
    }

    fn register_observer(&mut self, observer: Box<dyn FileObserver>) {
        self.observers.push(observer);
    }

    fn notify_rename(&self) {
        for observer in &self.observers {
            observer.on_rename(&self.path);
        }
    }

    fn notify_save(&self) {
        for observer in &self.observers {
            observer.on_save(&self.path);
        }
    }

    fn notify_close(&self) {
        for observer in &self.observers {
            observer.on_close(&self.path);
        }
    }
}

// Example implementation of a FileObserver
struct LoggingObserver;

impl FileObserver for LoggingObserver {
    fn on_rename(&self, file_path: &str) {
        println!("File {} was renamed", file_path);
    }

    fn on_save(&self, file_path: &str) {
        println!("File {} was saved", file_path);
    }

    fn on_close(&self, file_path: &str) {
        println!("File {} was closed", file_path);
    }
}

fn main() {
    let file = File::new("example.txt".to_string());
    let observer = Box::new(LoggingObserver);
    file.register_observer(observer);

    // Simulate file events
    file.notify_rename();
    file.notify_save();
    file.notify_close();
}
```

In this solution, we define a `FileObserver` trait with methods for handling file events and a `File` struct to represent the file being monitored. The `File` struct allows observers to register interest in specific file events and notifies them when those events occur. We also provide an example implementation of a `FileObserver` and demonstrate how to use the file monitoring system in the `main` function.

