    public void addItemListener(ItemListener listener) {
        itemListeners.add(listener);
    }

    public void removeItemListener(ItemListener listener) {
        itemListeners.remove(listener);
    }

    public void notifyDocumentListeners(DocumentEvent e) {
        for (DocumentListener listener : documentListeners) {
            listener.changedUpdate(e);
        }
    }

    public void notifyActionListeners(ActionEvent e) {
        for (ActionListener listener : actionListeners) {
            listener.actionPerformed(e);
        }
    }

    public void notifyItemListeners(ItemEvent e) {
        for (ItemListener listener : itemListeners) {
            listener.itemStateChanged(e);
        }
    }

