        description = new JTextArea();
        description.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                notifyDocumentListeners(e);
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                notifyDocumentListeners(e);
            }

            @Override
