  console.log('Event 2 handled with data:', data);
};

dispatcher.addListener('event1', eventHandler1);
dispatcher.addListener('event2', eventHandler2);

dispatcher.dispatchEvent('event1', { message: 'Hello from event 1' });
dispatcher.dispatchEvent('event2', { message: 'Hello from event 2' });

dispatcher.removeListener('event1', eventHandler1);

dispatcher.dispatchEvent('event1', { message: 'This will not be handled' });
```
